import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ReceptionistService } from '../../../core/services/receptionist.service';
import { Patient } from '../../../core/models';

@Component({
  selector: 'app-register-patient',
  templateUrl: './register-patient.component.html'
})
export class RegisterPatientComponent {

  form: FormGroup;
  loading = false;
  success = '';
  error = '';
  registeredPatient: Patient | null = null;

  constructor(private fb: FormBuilder, private receptionistService: ReceptionistService) {
    this.form = this.fb.group({
      name:   ['', [Validators.required, Validators.minLength(2)]],
      phone:  ['', [Validators.required, Validators.pattern(/^[0-9]{10,15}$/)]],
      email:  ['', Validators.email],
      age:    [null, [Validators.min(0), Validators.max(150)]],
      gender: ['']
    });
  }

  submit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';
    this.success = '';

    this.receptionistService.registerPatient(this.form.value).subscribe({
      next: patient => {
        this.registeredPatient = patient;
        this.success = `Patient registered. ID: ${patient.id}`;
        this.form.reset();
        this.loading = false;
      },
      error: err => {
        this.error = err.error?.message ?? 'Registration failed.';
        this.loading = false;
      }
    });
  }
}
<div class="page-header">
  <h2>Register Patient</h2>
  <p>Register a patient arriving offline at the reception desk</p>
</div>

<div class="card" style="max-width:520px;">
  <div *ngIf="success" class="alert alert-success">
    {{ success }}
    <br>
    <a routerLink="/receptionist/generate-token" style="color:#155724;font-weight:600;">
      → Generate Token for this patient
    </a>
  </div>
  <div *ngIf="error" class="alert alert-danger">{{ error }}</div>

  <form [formGroup]="form" (ngSubmit)="submit()">
    <div class="form-group">
      <label>Full Name *</label>
      <input formControlName="name" placeholder="Patient full name">
      <span class="error-msg" *ngIf="form.get('name')?.invalid && form.get('name')?.touched">
        Name is required
      </span>
    </div>
    <div class="form-group">
      <label>Phone Number *</label>
      <input formControlName="phone" placeholder="10-15 digit phone number">
      <span class="error-msg" *ngIf="form.get('phone')?.invalid && form.get('phone')?.touched">
        Valid phone number required (10–15 digits)
      </span>
    </div>
    <div class="form-group">
      <label>Email</label>
      <input type="email" formControlName="email" placeholder="patient@email.com (optional)">
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
      <div class="form-group">
        <label>Age</label>
        <input type="number" formControlName="age" placeholder="Age">
      </div>
      <div class="form-group">
        <label>Gender</label>
        <select formControlName="gender">
          <option value="">Select</option>
          <option value="MALE">Male</option>
          <option value="FEMALE">Female</option>
          <option value="OTHER">Other</option>
        </select>
      </div>
    </div>
    <button class="btn btn-primary" [disabled]="loading">
      {{ loading ? 'Registering...' : 'Register Patient' }}
    </button>
  </form>
</div>
